import type { UIMessage, UIMessagePart } from "@anvia/client";
import { createContext, createElement, type ReactElement, type ReactNode, useContext } from "react";

export type MessageContextValue = {
  message: UIMessage;
};

export type MessagePartContextValue = {
  isLive: boolean;
  part: UIMessagePart;
  streamControlled: boolean;
};

const MessageContext = createContext<MessageContextValue | undefined>(undefined);
const MessagePartContext = createContext<MessagePartContextValue | undefined>(undefined);

export function InternalMessageProvider({
  message,
  children,
}: {
  message: UIMessage;
  children?: ReactNode;
}): ReactElement {
  return createElement(MessageContext.Provider, { value: { message } }, children);
}

export function InternalMessagePartProvider({
  part,
  isLive = false,
  streamControlled = false,
  children,
}: {
  part: UIMessagePart;
  isLive?: boolean;
  streamControlled?: boolean;
  children?: ReactNode;
}): ReactElement {
  return createElement(
    MessagePartContext.Provider,
    { value: { isLive, part, streamControlled } },
    children,
  );
}

export function useMessage(): MessageContextValue {
  const value = useContext(MessageContext);
  if (value === undefined) {
    throw new Error(
      "Message primitives must be used inside MessagePrimitive.Root or ThreadPrimitive.Messages.",
    );
  }
  return value;
}

export function useMessagePart(): MessagePartContextValue {
  const value = useContext(MessagePartContext);
  if (value === undefined) {
    throw new Error(
      "Message part primitives must be used inside MessagePrimitive.Parts or MessagePrimitive.Part.",
    );
  }
  return value;
}

export function useOptionalMessagePart(): MessagePartContextValue | undefined {
  return useContext(MessagePartContext);
}
